   "sez": "mondo",
   "titolo": "Ex dipendente di OpenAI accusato di aver piazzato un dispositivo con il sostegno saudita",
   "orig": "Ex-OpenAI worker accused of planting device had Saudi support says court filing",
   "lead": "Secondo quanto emerge da un documento depositato in tribunale, un ex lavoratore di OpenAI accusato di aver installato un dispositivo non autorizzato avrebbe ricevuto il supporto del governo dell'Arabia Saudita. Le autorità giudiziarie stanno esaminando i dettagli della vicenda, mentre il governo saudita non ha risposto tempestivamente alle richieste di commento avanzate dalla stampa. Lo riferisce BBC News.",
   "more": [
    "Le aziende che operano nel settore dell'intelligenza artificiale avanzata gestiscono infrastrutture tecnologiche e dati di rilevanza strategica globale, rendendo la sicurezza dei propri impianti un obiettivo prioritario contro potenziali manomissioni o spionaggio."
   ],
