   "id": "zea85b175",
   "sez": "mondo",
   "titolo": "Portogallo, squalifica di trenta giorni e multa per Cristiano Ronaldo dopo una discussione con Jesus",
   "orig": "Ronaldo banned for 30 days, fined $285 by Portugal over spat with Jesus",
   "lead": "Il consiglio di disciplina della Federcalcio portoghese ha inflitto a Cristiano Ronaldo una squalifica della durata di un mese e una sanzione pecuniaria di 285 dollari. Il provvedimento disciplinare fa seguito a un alterco tra il calciatore e un membro dello staff identificato come Jesus. Lo riferisce Al Jazeera.",
   "more": [
    "Gli organi disciplinari delle federazioni calcistiche nazionali hanno il compito di sanzionare comportamenti scorretti o litigi avvenuti nell'ambito delle competizioni o durante i raduni delle rappresentative nazionali."
   ],
