   "sez": "prima",
   "titolo": "Francia, esteso il coprifuoco notturno a Parigi e in diverse città del nord",
   "orig": "France extends curfews to Paris after weekend unrest",
   "lead": "A seguito di un fine settimana segnato da gravi disordini e proteste, il governo francese ha imposto il coprifuoco notturno in alcune zone della capitale e in diverse città settentrionali. Le autorità locali e il primo ministro Sébastien Lecornu hanno adottato misure di restrizione della circolazione per contrastare la violenza e i saccheggi registrati nei giorni scorsi. Lo riferisce RTÉ News.",
   "more": [
    "L'imposizione di coprifuochi localizzati rappresenta uno strumento amministrativo d'emergenza volto a ridurre gli assembramenti notturni e a facilitare il lavoro delle forze dell'ordine nel controllo del territorio."
   ],
