   "titolo": "Nuova Zelanda, la decisione di Trade Me di vietare la vendita di pounamu grezzo definita una grande svolta",
   "orig": "Trade Me decision to ban raw pounamu 'a major breakthrough', Ngāi Tahu says",
   "lead": "La principale piattaforma di aste online della Nuova Zelanda, Trade Me, ha bloccato tutte le inserzioni attive e introdotto restrizioni per impedire la vendita futura di pietra verde grezza, nota come pounamu. L'organizzazione Ngāi Tahu ha accolto la misura definendola un importante passo avanti per la tutela del patrimonio culturale. Lo riferisce RNZ.",
   "more": [
    "Il pounamu, o giada della Nuova Zelanda, riveste un valore culturale, spirituale e tradizionale di primaria importanza per il popolo indigeno Māori della iwi Ngāi Tahu, che ne rivendica la proprietà e la protezione legale."
   ],
