   "id": "zaa6c0e98",
   "sez": "ambiente",
   "titolo": "Università sudafricane invitate a interrompere i legami con i combustibili fossili per sostenere l'azione climatica",
   "orig": "Wits and SA universities must cut fossil fuel ties to champion climate action",
   "lead": "Un rapporto pubblicato in Sudafrica evidenzia la mancanza di trasparenza e indipendenza delle università locali, in particolare l'università Wits, a causa dell'influenza esercitata dall'industria dei combustibili fossili tramite finanziamenti, ricerche e investimenti. Gli attivisti chiedono agli atenei di rendere noti i rapporti con le aziende energetiche, disinvestire dai combustibili fossili e promuovere una transizione verso l'energia pulita. Lo riferisce Daily Maverick.",
   "more": [
    "Il disinvestimento dai combustibili fossili è una strategia adottata da numerose istituzioni accademiche e finanziarie a livello globale per ridurre il sostegno economico all'industria del carbone, del petrolio e del gas e contrastare il cambiamento climatico."
   ],
