   "id": "zd497cf88",
   "sez": "ingegneria",
   "titolo": "Una club house rurale firmata Graham Baba nello Stato di Washington",
   "orig": "Golf clubhouse by Graham Baba nods to farm structures in rural Washington",
   "lead": "Lo studio statunitense Graham Baba Architects ha completato la ristrutturazione della club house e del campo pratica del Westwood Golf a Yakima, nello Stato di Washington. La struttura sorge in un'area agricola semi-arida nota per i suoi frutteti e i campi di luppolo. L'intervento punta a rinnovare il campo da golf a nove buche della cittadina rurale, integrando l'edificio nel paesaggio circostante attraverso l'impiego combinato di legno e cemento a vista sagomato con casseforme, materiali scelti per conferire calore, solidità e profondità visiva all'opera. Lo riferisce Dezeen.",
   "more": [
    "L'architettura rurale contemporanea integra spesso materiali tradizionali con tecniche moderne per ridurre l'impatto visivo sul territorio. L'uso del legno locale e del calcestruzzo a vista risponde alla duplice esigenza di garantire efficienza termica, resistenza alle escursioni climatiche e una continuità estetica con i fienili e le tipiche strutture agricole delle valli nordamericane."
   ],
