   "id": "zbfd49963",
   "sez": "adolescenti",
   "titolo": "Assemblee sindacali a scuola: i limiti orari per docenti e personale ATA",
   "orig": "Assemblea sindacale docenti e ATA: max 10 ore ogni anno, come posso distribuirle",
   "lead": "I lavoratori della scuola dispongono di un monte massimo di dieci ore annue retribuite per partecipare alle assemblee sindacali territoriali indette durante l'orario di servizio. Si discute delle modalità corrette con cui docenti e personale ATA possono frazionare queste ore, in particolare se sia possibile prendere parte soltanto a una frazione dell'incontro per poi rientrare in classe nelle ore successive, oppure se l'adesione vincoli a coprire l'intera durata dell'assemblea. La gestione dei permessi deve bilanciare il diritto sindacale con gli obblighi di vigilanza sugli studenti. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il contratto collettivo nazionale del comparto scuola disciplina la partecipazione sindacale stabilendo precisi adempimenti formali. I lavoratori devono comunicare l'adesione con congruo anticipo per consentire alle dirigenze scolastiche di riorganizzare gli orari delle lezioni, garantire il servizio minimo essenziale e avvisare tempestivamente le famiglie in merito a eventuali uscite anticipate degli alunni."
   ],
