   "id": "z90f589d6",
   "sez": "ambiente",
   "titolo": "Allarme Vespa orientalis a Roma: apicoltori preoccupati per il picco riproduttivo di ottobre",
   "orig": "Vespa Orientalis, è allarme a Roma e nella provincia. L?esperto: «Il picco del ciclo vitale è nel mese di ottobre». Apicoltori preoccupati",
   "lead": "A Roma e nei comuni della provincia si registrano continue segnalazioni per la proliferazione della Vespa orientalis, un calabrone alieno che suscita forti timori tra i cittadini e gli apicoltori. Gli esperti spiegano che proprio nel mese di ottobre la specie raggiunge il culmine del proprio ciclo vitale, intensificando le attività per assicurare la riproduzione prima dell'inverno. L'aggressività delle colonie mette in grave pericolo gli alveari locali, assediati dagli insetti predatori, costringendo gli operatori a sollecitare interventi di bonifica tempestivi nei quartieri urbani e nelle aree agricole limitrofe. Lo riferisce Il Messaggero – Roma.",
   "more": [
    "La Vespa orientalis è una specie diffusa tradizionalmente nel Mediterraneo orientale e in Medio Oriente, la cui espansione verso nord è favorita dalle temperature invernali più miti. Questo imenottero attacca le api operaie per nutrire le proprie larve, provocando la distruzione delle arnie e alterando l'attività d'impollinazione indispensabile per la flora."
   ],
