   "id": "zf0918029",
   "sez": "mondo",
   "titolo": "La guerra in Iran accende la rabbia economica negli USA e mette a rischio la maggioranza repubblicana",
   "orig": "Iran War backlash threatens Republican control of Congress",
   "lead": "Le ricadute del conflitto bellico contro l'Iran stanno alimentando un forte malcontento tra gli elettori statunitensi, mettendo a repentaglio il controllo repubblicano sul Congresso degli Stati Uniti. La contrarietà dell'opinione pubblica all'intervento militare è acuita dagli effetti economici della crisi, con l'aumento dei costi energetici e le incertezze finanziarie che pesano sulle famiglie. Secondo gli analisti, la rabbia popolare per le conseguenze materiali delle operazioni all'estero rischia di tradursi in una severa punizione elettorale per la maggioranza conservatrice alle urne. Lo riferisce Al Jazeera.",
   "more": [
    "Negli Stati Uniti la politica estera e gli impegni militari in Medio Oriente hanno storicamente un forte impatto sulle elezioni legislative di metà mandato. Le impennate dei prezzi del carburante e l'inflazione derivanti dalle tensioni nell'area del Golfo Persico orientano rapidamente il consenso popolare contro i partiti di governo."
   ],
