   "sez": "tech",
   "titolo": "Falana esorta i giovani nigeriani a ripudiare le truffe online e valorizzare la tecnologia legale",
   "orig": "Afe Babalola Day: Falana laments youth involvement in internet fraud, urges legitimate technology use",
   "lead": "In occasione delle celebrazioni dell'Afe Babalola Day in Nigeria, il noto avvocato e attivista per i diritti umani Femi Falana ha lanciato un accorato appello contro il coinvolgimento delle nuove generazioni nelle frodi telematiche. Falana ha espresso rammarico per la diffusione della criminalità informatica tra i giovani, esortandoli a prendere esempio dalla vita e dalla disciplina di Babalola. Ha ribadito che l'impegno nello studio, la determinazione e l'uso produttivo e lecito delle nuove tecnologie rappresentano l'unica via per superare le difficoltà sociali ed economiche. Lo riferisce Premium Times.",
   "more": [
    "In Nigeria il fenomeno delle truffe informatiche, noto localmente con il termine galamsey o yahoo-yahoo, ha spinto le autorità a rafforzare la repressione penale per difendere la reputazione del paese. Parallelamente, Lagos è diventata uno dei principali hub di start-up tecnologiche e informatiche del continente africano."
   ],
