   "lead": "La piattaforma Lezhin Entertainment ha annunciato il lancio in Corea del Sud di Teaz, un nuovo servizio di chat basato sull'intelligenza artificiale. L'applicazione permette agli utenti di interagire direttamente con i personaggi tratti dalle serie originali pubblicate su Lezhin Comics e Bomtoon. L'iniziativa punta a offrire un'esperienza immersiva per i lettori delle celebri serie a fumetti. Lo riferisce Anime News Network.",
