   "lead": "Un gruppo di ricercatori ha confermato l'esistenza del primo microblazar all'interno della Via Lattea. A differenza dei blazar tradizionali, che si trovano oltre i confini galattici e sono alimentati da buchi neri supermassicci, questo oggetto è alimentato da un buco nero di massa stellare e potrebbe rappresentare la fonte delle particelle più energetiche della galassia. Lo riferisce Universe Today.",
