   "lead": "Gli insegnanti della Grecia terranno uno sciopero di 24 ore per protestare contro la carenza di personale scolastico, i problemi nelle infrastrutture, le classi troppo numerose e le inadeguatezze persistenti nelle strutture in tutto il Paese. La mobilitazione è sostenuta da studenti delle scuole superiori, universitari e partiti di sinistra. Lo riferisce Keep Talking Greece.",
