   "lead": "L'ufficio doganale di Birgunj, in Nepal, ha registrato un gettito di entrate pari a 26,73 miliardi di rupie tra la metà di settembre e la metà di ottobre, superando l'obiettivo prefissato di 26,46 miliardi. Il risultato è stato trainato dall'incremento delle importazioni di merci in vista delle festività tradizionali di Dashain, Tihar e Chhath. Lo riferisce The Kathmandu Post.",
