   "lead": "La riduzione del debito pubblico potrebbe risanare le finanze del Sudafrica e migliorarne il rating creditizio, ma il percorso di risanamento incontra diversi ostacoli interni. Tra i fattori che minacciano i progressi figurano le politiche di austerità, le questioni relative al prezzo dei carburanti e la resistenza politica da parte dell'African National Congress. Lo riferisce Daily Maverick.",
