   "titolo": "Fattori economici e abitudini sociali dietro la percezione della giovinezza fino a 35 anni in Italia",
   "orig": "Perché a 35 anni si è ancora considerati “giovani” in Italia: dipende da abitudini e capacità economiche",
   "lead": "In Italia la soglia per essere considerati giovani si estende in alcuni contesti fino ai 35 anni, un limite non ufficiale influenzato dalle abitudini di vita e dalle capacità economiche che determinano l'ingresso ritardato nella vita adulta. Lo riferisce Geopop.",
   "more": [
    "I cambiamenti socioeconomici, tra cui le difficoltà di inserimento stabile nel mercato del lavoro e l'aumento dei costi abitativi, hanno modificato nel tempo i tempi e le modalità con cui i giovani raggiungono l'indipendenza economica e familiare."
   ],
